package com.hbm.machine.gascentrifuge;
import com.hbm.multiblock.DummyableBlock;import com.mojang.serialization.MapCodec;import net.minecraft.core.BlockPos;import net.minecraft.world.level.*;import net.minecraft.world.level.block.SoundType;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.material.MapColor;import net.minecraft.world.phys.shapes.*;
/** Original four-block column, full foot and 7/8-wide 3-block vessel. */
public final class GasCentrifugeBlock extends DummyableBlock {
 private static final MapCodec<GasCentrifugeBlock> CODEC=simpleCodec(p->new GasCentrifugeBlock());public GasCentrifugeBlock(){super(Properties.of().mapColor(MapColor.METAL).strength(5,6).sound(SoundType.STONE).requiresCorrectToolForDrops().noOcclusion());}@Override protected MapCodec<? extends DummyableBlock> codec(){return CODEC;}@Override public int[] dimensions(){return new int[]{3,0,0,0,0,0};}
 @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return isCore(state)?new GasCentrifugeBlockEntity(pos,state):isPort(state)?new GasCentrifugePort(pos,state):null;}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return isCore(state)?createTickerHelper(type,GasCentrifugeContent.ENTITY.get(),GasCentrifugeBlockEntity::tick):null;}
 @Override protected VoxelShape getShape(BlockState state,BlockGetter level,BlockPos pos,CollisionContext context){var core=findCore(level,pos);return core==null?Shapes.empty():core.equals(pos)?box(0,0,0,16,15.984,16):box(1,0,1,15,16,15);}@Override protected VoxelShape getCollisionShape(BlockState state,BlockGetter level,BlockPos pos,CollisionContext context){var core=findCore(level,pos);return core==null?Shapes.empty():core.equals(pos)?Shapes.block():box(1,0,1,15,16,15);}
}
